package com.starlight.greetings.web; import com.starlight.greetings.application.*; import jakarta.servlet.http.HttpServletRequest; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin") public class AdminOperationsController {private final AdminOperationsService s;private final SessionService auth;public AdminOperationsController(AdminOperationsService s,SessionService auth){this.s=s;this.auth=auth;}private String admin(String csrf,HttpServletRequest r){return auth.admin(SessionCookie.token(r),csrf).id();}private void read(HttpServletRequest r){auth.adminRead(SessionCookie.token(r));}@GetMapping("/questions") public ApiEnvelope<List<Map<String,Object>>> questions(@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){read(r);return ApiEnvelope.of(s.questions());}@PostMapping("/questions") public ResponseEntity<ApiEnvelope<Map<String,Object>>> question(@RequestBody Map<String,Object> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ResponseEntity.status(201).body(ApiEnvelope.of(s.createQuestion(v,admin(c,r))));}@PatchMapping("/questions/{id}") public ApiEnvelope<Map<String,Object>> questionPatch(@PathVariable String id,@RequestBody Map<String,String> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ApiEnvelope.of(s.editQuestion(id,v.get("body"),admin(c,r)));}@GetMapping("/seeds") public ApiEnvelope<List<Map<String,Object>>> seeds(@RequestParam(required=false)String bridgeId,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){read(r);return ApiEnvelope.of(s.seeds(bridgeId));}@PostMapping("/seeds") public ResponseEntity<ApiEnvelope<Map<String,Object>>> seed(@RequestBody Map<String,Object> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ResponseEntity.status(201).body(ApiEnvelope.of(s.createSeed(v,admin(c,r))));}@PatchMapping("/seeds/{id}") public ApiEnvelope<Map<String,Object>> seedPatch(@PathVariable String id,@RequestBody Map<String,Object> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ApiEnvelope.of(s.editSeed(id,v,admin(c,r)));}@GetMapping("/letters") public ApiEnvelope<List<Map<String,Object>>> letters(@RequestParam String query,@RequestParam(required=false)String bridgeId,HttpServletRequest r){read(r);return ApiEnvelope.of(s.findLetters(query,bridgeId));}@GetMapping("/alerts") public ApiEnvelope<Map<String,Object>> alerts(HttpServletRequest r){read(r);return ApiEnvelope.of(s.alerts());}@GetMapping("/inquiries") public ApiEnvelope<List<Map<String,Object>>> inquiries(@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){read(r);return ApiEnvelope.of(s.inquiries());}@PatchMapping("/inquiries/{id}") public ApiEnvelope<Map<String,Object>> inquiry(@PathVariable String id,@RequestBody Map<String,String> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ApiEnvelope.of(s.updateInquiry(id,v.get("status"),v.get("reason"),admin(c,r)));}@GetMapping("/moderation-rules") public ApiEnvelope<List<Map<String,Object>>> rules(@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){read(r);return ApiEnvelope.of(s.rules());}@PostMapping("/moderation-rules") public ResponseEntity<ApiEnvelope<Map<String,Object>>> rule(@RequestBody Map<String,Object> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ResponseEntity.status(201).body(ApiEnvelope.of(s.createRule(v,admin(c,r))));}@PatchMapping("/moderation-rules/{id}") public ApiEnvelope<Map<String,Object>> rulePatch(@PathVariable String id,@RequestBody Map<String,Object> v,@RequestHeader(value="x-csrf-token",required=false)String c,HttpServletRequest r){return ApiEnvelope.of(s.setRule(id,v.get("active") instanceof Boolean b?b:null,(String)v.get("reason"),admin(c,r)));}}
